Scheme kc__1 := Elimination for OSSVerify.Proofs.boost_beast.http_request.lib.As.AsTailExit.TailExit.exitH Sort Prop.
Scheme kc__2 := Elimination for Corelib.Init.Logic.and Sort Prop.

  Theorem tail_exit2 : forall regs mem mem' msF mo (sp : word) (FR tid can : Z) (ro wpw we re : word),
    exitH mem sp tid ro wpw ->
    (bv_unsigned sp mod 16 = 0)%Z -> (ASP_LO <= bv_unsigned sp)%Z -> (bv_unsigned sp <= ASP_HI)%Z ->
    (forall i, (0x10000 <= i < 0x4d000)%Z -> mem (Z_to_bv 64 i) = None) ->
    (forall i, (0x115000 <= i < 0x11d000)%Z -> mem (Z_to_bv 64 i) = None) ->
    frame_mod mem mem' (tail_regions sp FR) -> (400 <= FR <= 8388608)%Z ->
    stk_ok RSEGS mem' sp 400 ->
    (0 <= can < 2 ^ 64)%Z -> rdn RSEGS mem' (Z_to_bv 64 0x67d4f0) 8 = Some (word_to_le_bytes 8 (Z_to_bv 64 can)) ->
    rdn RSEGS mem' (Z_to_bv 64 0x11fc58) 8 = Some (word_to_le_bytes 8 we) ->
    rdn RSEGS mem' (Z_to_bv 64 0x11fc68) 8 = Some (word_to_le_bytes 8 we) ->
    rdn RSEGS mem' (Z_to_bv 64 0x11fc38) 8 = Some (word_to_le_bytes 8 re) ->
    rdn RSEGS mem' (Z_to_bv 64 0x11fc40) 8 = Some (word_to_le_bytes 8 re) ->
    rdn RSEGS mem' (Z_to_bv 64 0x11fcbc) 4 = Some (word_to_le_bytes 4 (Z_to_bv 64 4294967295)) ->
    getr regs 2 = sp -> getr regs 4 = Z_to_bv 64 0x65d4b0 -> getr regs 10 = Z_to_bv 64 2 ->
    lzok RSEGS L S Zr (mkCfg msF mo) -> restrict L S msF = mkst regs (Z_to_bv 64 AEXIT) mem' (seg_rom RSEGS) ->
